@Test
public void testGetSurrogateKey() {
    columnDictionaryInfo = new ColumnDictionaryInfo(DataType.STRING);
    byte[] value = convertListElementsIntoByteArray(Arrays.asList("china")).get(0);
    new MockUp<CarbonUtil>() {

        @Mock
        public int getDictionaryChunkSize() {
            return 10000;
        }
    };
    columnDictionaryInfo.setSortOrderIndex(Arrays.asList(1, 2, 3, 4, 5, 6, 7));
    List<byte[]> chunks = Arrays.asList(new byte[] { 64, 78, 85, 35, 76, 76, 36, 33 }, new byte[] { 98, 114, 97, 122, 105, 108 }, new byte[] { 99, 97, 110, 97, 100, 97 }, new byte[] { 99, 104, 105, 110, 97 }, new byte[] { 102, 114, 97, 110, 99, 101 }, new byte[] { 117, 107 }, new byte[] { 117, 117, 97 });
