 */
@Test
public void getValueFromSurrogate() throws Exception {
    TimeStampDirectDictionaryGenerator generator = new TimeStampDirectDictionaryGenerator();
    long valueFromSurrogate = (long) generator.getValueFromSurrogate(surrogateKey);
    Date date = new Date(valueFromSurrogate / 1000);
    SimpleDateFormat timeParser = new SimpleDateFormat(CarbonProperties.getInstance().getProperty(CarbonCommonConstants.CARBON_TIMESTAMP_FORMAT, CarbonCommonConstants.CARBON_TIMESTAMP_DEFAULT_FORMAT));
